      "import type { PropsBaseType } from '@proto.ui/types';\nimport type { AnatomyPartView } from './anatomy';\nimport type { ObservedStateHandle } from './state';\nimport type {\n  AnchoredCollisionBoundary,\n  AnchoredPositionSnapshot,\n  AnchoredPositionStrategy,\n} from './positioning';\n\nexport type OverlayPlacement = 'top' | 'right' | 'bottom' | 'left';\nexport type OverlayAlign = 'start' | 'center' | 'end';\n\nexport type OverlayFocusEntry = 'first' | 'selected' | 'content' | 'manual';\nexport type OverlayFocusRestore = 'trigger' | 'previous' | 'none';\nexport type OverlayLayerRole = 'overlay' | 'dialog-mask' | 'dialog-content' | (string & {});\n\nexport type OverlayReason =\n  | 'trigger.press'\n  | 'trigger.hover'\n  | 'context.menu'\n  | 'escape'\n  | 'outside.press'\n  | 'focus.outside'\n  | 'item.commit'\n  | 'controlled.sync'\n  | 'programmatic'\n  | (string & {});\n\nexport type OverlayConfigPatch = Readonly<{\n  defaultOpen?: boolean;\n  closeOnEscape?: boolean;\n  closeOnOutsidePress?: boolean;\n  closeOnFocusOutside?: boolean;\n  closeOnAnchorPress?: boolean;\n  closeOnTriggerPress?: boolean;\n  placement?: OverlayPlacement;\n  align?: OverlayAlign;\n  sideOffset?: number;\n  alignOffset?: number;\n  anchored?: boolean;\n  /** Project a host-root available region without choosing placement or visual gutters. */\n  availableSpace?: boolean;\n  availableLayout?: import('./positioning').AvailableLayoutBinding;\n  strategy?: AnchoredPositionStrategy;\n  avoidCollisions?: boolean;\n  collisionBoundary?: AnchoredCollisionBoundary;\n  collisionPadding?: number;\n  excludeAnchorTranslation?: boolean;\n  entry?: OverlayFocusEntry;\n  restore?: OverlayFocusRestore;\n  portal?: boolean;\n  modal?: boolean;\n  layerRole?: OverlayLayerRole;\n  layerOffset?: number;\n  meta?: Readonly<Record<string, unknown>>;\n}>;\n\nexport type OverlayConfig = Readonly<{\n  defaultOpen: boolean;\n  closeOnEscape: boolean;\n  closeOnOutsidePress: boolean;\n  closeOnFocusOutside: boolean;\n  closeOnAnchorPress: boolean;\n  closeOnTriggerPress: boolean;\n  placement: OverlayPlacement;\n  align: OverlayAlign;\n  sideOffset: number;\n  alignOffset: number;\n  anchored: boolean;\n  availableSpace?: boolean;\n  availableLayout?: import('./positioning').AvailableLayoutBinding;\n  strategy: AnchoredPositionStrategy;\n  avoidCollisions: boolean;\n  collisionBoundary: AnchoredCollisionBoundary;\n  collisionPadding: number;\n  excludeAnchorTranslation: boolean;\n  entry: OverlayFocusEntry;\n  restore: OverlayFocusRestore;\n  portal: boolean;\n  modal: boolean;\n  layerRole: OverlayLayerRole;\n  layerOffset: number;\n  meta?: Readonly<Record<string, unknown>>;\n}>;\n\nexport type OverlayPositionPatch = Readonly<\n  Pick<\n    OverlayConfigPatch,\n    | 'placement'\n    | 'align'\n    | 'sideOffset'\n    | 'alignOffset'\n    | 'strategy'\n    | 'avoidCollisions'\n    | 'collisionBoundary'\n    | 'collisionPadding'\n    | 'excludeAnchorTranslation'\n  >\n>;\n\nexport type OverlayRegistration = Readonly<{\n  trigger: unknown | null;\n  anchor: unknown | null;\n  content: unknown | null;\n}>;\n\n/**\n * Supplies perceptual presence for an overlay. Only the active binding may\n * submit structural ViewIntent; binding a transition disables Overlay's\n * immediate presence driver.\n */\nexport type OverlayPresenceBinding<P extends PropsBaseType = PropsBaseType> = Readonly<{\n  enter(): void;\n  leave(): void;\n  present: ObservedStateHandle<boolean, any>;\n}>;\n\n/** Runtime-only safe-part association; no host target reaches the author. */\nexport type OverlayTargetAlignmentBinding = Readonly<{\n  family: import('./anatomy').AnatomyFamily;\n  surface: AnatomyPartView;\n  scrollport: AnatomyPartView;\n  blockReference: AnatomyPartView;\n  inlineReference: AnatomyPartView;\n  blockTarget: AnatomyPartView;\n  inlineTarget: AnatomyPartView;\n  atStart: boolean;\n  atEnd: boolean;\n  constraints: import('./positioning').TargetAlignmentConstraints;\n  /** Safe parts only; physical size facts stay inside Positioning. */\n  sizeMatch?: Readonly<{ reference: AnatomyPartView; targets: readonly AnatomyPartView[] }>;\n  onAlignment(status: import('./positioning').TargetAlignmentStatus): void;\n}>;\n\n/** Independent safe-part edge sizing; no physical target or selection policy reaches the author. */\nexport type OverlaySizeMatchBinding = Readonly<{\n  family: import('./anatomy').AnatomyFamily;\n  surface: AnatomyPartView;\n  reference: AnatomyPartView;\n  targets: readonly AnatomyPartView[];\n  onSizeMatch(status: import('./positioning').TargetAlignmentStatus): void;\n}>;\n\nexport interface OverlayModuleHandle<P extends PropsBaseType = PropsBaseType> {\n  open: ObservedStateHandle<boolean, P>;\n\n  /** One current open-view resource pass; not renderer/native readiness. */\n  afterViewReconciled(callback: () => void): () => void;\n\n  isOpen(): boolean;\n  openOverlay(reason?: OverlayReason): void;\n  close(reason?: OverlayReason): void;\n  toggle(reason?: OverlayReason): void;\n\n  configure(patch: OverlayConfigPatch): void;\n  updatePosition(patch: OverlayPositionPatch): void;\n\n  registerTrigger(target: unknown): void;\n  registerAnchor(target: unknown): void;\n  /** Position only; existing anatomy still owns dismissal and focus restoration. */\n  registerInputAnchor(anchor: import('./context-menu-input').InputOriginAnchor | null): void;\n  registerAnchorPart(part: AnatomyPartView): void;\n  registerContent(target: unknown): void;\n  registerTargetAlignment(binding: OverlayTargetAlignmentBinding | null): void;\n  registerSizeMatch(binding: OverlaySizeMatchBinding | null): void;\n  getPositionSnapshot(): AnchoredPositionSnapshot | null;\n}\n\nexport interface OverlayHandle<\n  P extends PropsBaseType = PropsBaseType,\n> extends OverlayModuleHandle<P> {\n  /** Keeps the host view mounted while logical open still gates Overlay resources. */\n  keepMounted(): void;\n  bindPresence(binding: OverlayPresenceBinding<P>): void;\n}\n",
